"use client";

import { useEffect, useState, useCallback } from "react";
import { ChevronLeft, ChevronRight, ExternalLink, History, Scale } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { getTrades } from "@/lib/api";
import { formatAddress, formatRelativeTime, formatSol, formatTokenAmount } from "@/lib/format";
import type { Trade } from "@/lib/types";

type Props = { address: string };

export function TradeHistoryTable({ address }: Props) {
  const [trades, setTrades] = useState<Trade[]>([]);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async (targetPage: number) => {
    setLoading(true);
    try {
      const res = await getTrades(address, targetPage, 20);
      setTrades(res.trades);
      setTotalPages(Math.max(1, res.totalPages));
    } finally {
      setLoading(false);
    }
  }, [address]);

  useEffect(() => {
    load(page);
  }, [load, page]);

  return (
    <Card className="border-border/60">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="flex items-center gap-2 text-base">
          <History className="size-4 text-primary" /> Trade history
        </CardTitle>
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Button
            variant="outline"
            size="icon"
            className="size-7"
            disabled={page <= 1 || loading}
            onClick={() => setPage((p) => Math.max(1, p - 1))}
          >
            <ChevronLeft className="size-3.5" />
          </Button>
          <span className="tabular-nums">
            {page} / {totalPages}
          </span>
          <Button
            variant="outline"
            size="icon"
            className="size-7"
            disabled={page >= totalPages || loading}
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
          >
            <ChevronRight className="size-3.5" />
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {loading && trades.length === 0 ? (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 5 }).map((_, i) => (
              <Skeleton key={i} className="h-10 w-full" />
            ))}
          </div>
        ) : trades.length === 0 ? (
          <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed border-border/60 py-10 text-center text-sm text-muted-foreground">
            No trades recorded yet
          </div>
        ) : (
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Type</TableHead>
                  <TableHead>Mint</TableHead>
                  <TableHead className="text-right">Tokens</TableHead>
                  <TableHead className="text-right">SOL</TableHead>
                  <TableHead>Program</TableHead>
                  <TableHead>Tx</TableHead>
                  <TableHead className="text-right">Time</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {trades.map((trade) => (
                  <TableRow key={trade._id}>
                    <TableCell>
                      <Badge
                        variant="outline"
                        className={
                          trade.type === "buy"
                            ? "border-positive/30 text-positive"
                            : "border-negative/30 text-negative"
                        }
                      >
                        {trade.type === "buy" ? "Buy" : "Sell"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <a
                        href={`https://pump.fun/coin/${trade.mint}`}
                        target="_blank"
                        rel="noreferrer"
                        className="inline-flex items-center gap-1 font-mono text-xs text-muted-foreground hover:text-primary"
                      >
                        {formatAddress(trade.mint, 5)}
                        <ExternalLink className="size-3" />
                      </a>
                    </TableCell>
                    <TableCell className="text-right tabular-nums">{formatTokenAmount(trade.tokenAmount)}</TableCell>
                    <TableCell className="text-right tabular-nums">
                      <span className="inline-flex items-center justify-end gap-1">
                        {formatSol(trade.solAmount)}
                        {trade.solAmountSource === "wallet_balance_delta" && (
                          <Tooltip>
                            <TooltipTrigger asChild>
                              <Scale className="size-3 text-muted-foreground" />
                            </TooltipTrigger>
                            <TooltipContent>
                              Inferred from this wallet&apos;s net SOL balance change — the trade wasn&apos;t
                              quoted directly in SOL (e.g. routed through another token), so this is the real
                              SOL impact rather than a value read off the trade itself.
                            </TooltipContent>
                          </Tooltip>
                        )}
                      </span>
                    </TableCell>
                    <TableCell>
                      <Badge variant="secondary" className="font-normal">
                        {trade.program}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <a
                        href={`https://solscan.io/tx/${trade.signature}`}
                        target="_blank"
                        rel="noreferrer"
                        className="inline-flex items-center gap-1 font-mono text-xs text-muted-foreground hover:text-primary"
                      >
                        {formatAddress(trade.signature, 5)}
                        <ExternalLink className="size-3" />
                      </a>
                    </TableCell>
                    <TableCell className="text-right text-xs text-muted-foreground">
                      {formatRelativeTime(trade.blockTime ? trade.blockTime * 1000 : trade.recordedAt)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </CardContent>
    </Card>
  );
}
