"use client";

import { Coins, Wallet } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatAddress, formatSol, formatTokenAmount, formatUsd } from "@/lib/format";
import type { Holding } from "@/lib/types";

type Props = {
  holdings: Holding[];
  holdingsValueUsd: number;
};

export function HoldingsPanel({ holdings, holdingsValueUsd }: Props) {
  return (
    <Card className="border-border/60">
      <CardHeader className="flex flex-row items-center justify-between">
        <CardTitle className="flex items-center gap-2 text-base">
          <Wallet className="size-4 text-primary" /> Open positions
        </CardTitle>
        {holdings.length > 0 && (
          <span className="text-sm font-medium tabular-nums text-muted-foreground">
            {formatUsd(holdingsValueUsd)} total
          </span>
        )}
      </CardHeader>
      <CardContent className="flex flex-col gap-3">
        {holdings.length === 0 ? (
          <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed border-border/60 py-10 text-center text-sm text-muted-foreground">
            <Coins className="size-5 opacity-50" />
            No open positions
          </div>
        ) : (
          holdings.map((holding) => (
            <div
              key={holding.mint}
              className="flex items-center justify-between gap-3 rounded-lg border border-border/60 bg-muted/30 p-3"
            >
              <div className="flex flex-col gap-0.5">
                <span className="text-sm font-medium">
                  {holding.symbol ? `$${holding.symbol}` : formatAddress(holding.mint)}
                </span>
                {holding.name && <span className="text-xs text-muted-foreground">{holding.name}</span>}
                <span className="font-mono text-[11px] text-muted-foreground">{formatAddress(holding.mint, 6)}</span>
              </div>
              <div className="flex flex-col items-end gap-0.5">
                <span className="text-sm font-medium tabular-nums">{formatTokenAmount(holding.tokenAmount)} tokens</span>
                <span className="text-xs text-muted-foreground tabular-nums">cost basis {formatSol(holding.solCostBasis)}</span>
                <span className="text-xs font-medium tabular-nums text-primary">
                  {holding.currentValueUsd !== null ? `${formatUsd(holding.currentValueUsd)} now` : "price unavailable"}
                </span>
              </div>
            </div>
          ))
        )}
      </CardContent>
    </Card>
  );
}
